import openpyxl
from openpyxl.styles import PatternFill

wb = openpyxl.load_workbook(INPUT_PATH)
ws = wb["訂單"]

green_fill = PatternFill(start_color="C6EFCE", end_color="C6EFCE", fill_type="solid")

# 資料從第 2 列到第 14 列，金額在 H 欄 (第 8 欄)
for row in ws.iter_rows(min_row=2, max_row=14, min_col=1, max_col=8):
    amount = row[7].value
    if amount is None:
        continue

    if amount >= 19400:
        for cell in row:
            cell.fill = green_fill
    elif amount < 5530:
        for cell in row:
            # 保留原本字體的其他屬性，僅修改顏色為紅色
            cell.font = cell.font.copy(color="FF0000")

wb.save(OUTPUT_PATH)
